/** Result shape tauri-specta emits for commands that return `Result<T, String>`. */
type CmdResult<T> = { status: "ok"; data: T } | { status: "error"; error: string };

/** Unwrap a Result-returning command, throwing the error string on failure. */
export async function unwrap<T>(p: Promise<CmdResult<T>>): Promise<T> {
  const r = await p;
  if (r.status === "error") throw new Error(r.error);
  return r.data;
}
